{
  "description": "The creature is a quadrupedal, bear-like animal shown in right-facing profile against a plain light background. It has the head, dense brown fur, and clawed paws of a brown bear, but most of its dorsal surface, sides, chest, and outer limbs are covered by a glossy, dark brown to black, segmented exoskeleton-like armor. A single long, smooth, black, sickle-shaped horn rises from the center of the forehead and curves backward and then forward to a sharp point. The body is stocky and low to the ground, with four thick legs ending in broad paws with visible claws, a short rear tail with a furry tip and armored base, and brown fur visible on the head, neck, underbelly, and around the joints between the plates.",
  "parts": [
    {
      "part": "head",
      "looks_like": "a brown bear head with dense brown fur, lighter tan muzzle, black nose, small brown eyes, white whiskers, and rounded snout",
      "where": "at the front of the body, facing right"
    },
    {
      "part": "horns",
      "looks_like": "one long, glossy, smooth black horn, thick at the base and tapering to a sharp tip, strongly curved backward in a sickle shape",
      "where": "emerging from the midline of the forehead on top of the head between the ears"
    },
    {
      "part": "ears",
      "looks_like": "two small, rounded, furry brown ears with dense fur",
      "where": "on top of the head on either side of the horn base"
    },
    {
      "part": "legs",
      "looks_like": "four thick, muscular legs with brown fur and overlaid glossy dark segmented plates on the upper thigh/shoulder and lower shin areas, with lighter tan segmented skin visible on the underbelly and inner joints",
      "where": "under the body, two front legs under the chest and two hind legs under the rear, supporting the body"
    },
    {
      "part": "feet",
      "looks_like": "four broad bear paws covered in brown fur with five long, curved, light tan to dark claws on each",
      "where": "at the ends of the four legs in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "a short tail with a tuft of brown fur at the tip and a dorsal covering of small dark segmented plates continuing from the back",
      "where": "at the extreme rear of the body, extending slightly downward"
    },
    {
      "part": "shell",
      "looks_like": "a large, glossy, dark brown-black domed carapace made of overlapping transverse segments with smooth shiny surfaces and small oval holes along the lower edge",
      "where": "covering the entire back from behind the neck to the base of the tail"
    },
    {
      "part": "plates",
      "looks_like": "glossy dark brown-black segmented armor plates, smooth and slightly reflective, with distinct segment lines; includes shoulder caps, thigh caps, shin guards, and chest plates, with tan segmented skin and circular pores visible between them",
      "where": "on the sides of the neck and chest, over the shoulders and thighs, and wrapped around the lower front and hind legs"
    }
  ],
  "attached_objects": [],
  "animals": [
    "bear",
    "woodlouse",
    "rhinoceros beetle"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
